//! CHARTER: Vug (CODEX §2, 3D), a host face — the feature tree (VUGFACETREE, LEDGER SR513): the face's actions as
//! doc_core statements, undo / redo as Doc snapshots, the face regenerated by doc_core::replay; holds no geometry.
//!
//! "The feature tree must not break" (docs/dev/USERLAND/VUG.md §3 principle 3). The DOCUMENT is the face's truth:
//! every committed face action (a stroke's release, the arc's end click, an erase, a dimension's Enter, a committed
//! pull) calls [`Journal::record`], which re-writes the open sketch's statements from the face (THE face -> Doc writer:
//! [`cons`] / [`pref`] / [`sketch_doc`]) behind the frozen statements of the closed sketches and features, and appends
//! the extrude of a committed pull. A changed document pushes the old one on a snapshot stack bounded by
//! [`UNDO_DEPTH`]. When the history is edited — `u` / `U`, a statement deleted or a value changed in the panel — the
//! face and the body are regenerated by [`regenerate`] (doc_core's `replay`: the open sketch to a SketchFace, the solids
//! to the Body), so the tree never shows something the geometry is not; a replay failure names its line in the panel
//! and keeps the last good geometry and document. A deleted statement takes its dependants with it through doc_core's
//! own reader (`What::UnknownRef` by line) and replay (`Fault::Upstream` by line); `diff`'s Removed names them.
//! A committed fillet / chamfer of the face (fillet.rs) enters by [`Journal::record_edit`] after the frozen features
//! (VUGFACETREEFILLET, SR518); in the Body an edit's solid stands in its `on` solid's place ([`live_solids`]).
//! Its row's value is its radius (a chamfer's `d1`, typed `d1,d2` through [`type_pair`]): an edit re-fillets through
//! replay, and a brep_core refusal (`RadiusTooLarge`) names the line and keeps the last good body (VUGFACETREEEDITR, SR528).
//!
//! Ids: sketch 0 is `s` with entities `e<n>` and constraints `k<n>`, sketch j > 0 is `s<j>` with `s<j>e<n>` /
//! `s<j>k<n>`, extrudes `x<n>`, fillets `f<n>`, chamfers `c<n>`; a face slot keeps its name across regenerates (the slot maps in `Open`).

use crate::extrude::{Body, Pull};
use crate::raster::{self, Frame as Raster, rgba};
use crate::sketch::{ACTIVE, Design, Dim, Dimension, INK, REFUSED, SketchFace, type_into};
use crate::view::View;
use brep_core::Frame;
use doc_core::{Cons, Doc, Entry, Fault, PRef, PlainNames, SketchNames, Stmt, Tol, What};
use sketch_core::{ConstraintId, EntityId, Vec2};

/// The snapshots kept for undo (and for redo): one per committed action that changed the document, the oldest
/// dropped. Memory is this many documents (a document is its statements: a few hundred bytes a statement).
pub const UNDO_DEPTH: usize = 64;

/// The id of the first sketch (VUGFACEPHOTO's `photo::SKETCH_ID` names the same statement).
pub const FIRST_SKETCH: &str = "s";

/// A panel row's height, surface pixels.
pub const ROW_PX: f32 = 14.0;

/// The open sketch: its statement id, the prefix of its entity / constraint ids, the face slot -> doc id maps (every
/// slot, tombstones included) and the next free numbers.
#[derive(Clone, Debug, Default)]
struct Open {
    sketch: String,
    prefix: String,
    ents: Vec<String>,
    cons: Vec<String>,
    next_e: u32,
    next_k: u32,
}

impl Open {
    fn fresh(sketch: String) -> Open {
        let prefix = if sketch == FIRST_SKETCH { String::new() } else { sketch.clone() };
        Open { sketch, prefix, ..Default::default() }
    }

    /// Name every face slot not yet named (entities to the end of the entity list, constraints below `issued`).
    fn name_slots(&mut self, f: &SketchFace) {
        while self.ents.len() < f.sketch.entities().len() {
            self.ents.push(format!("{}e{}", self.prefix, self.next_e));
            self.next_e += 1;
        }
        while self.cons.len() < f.issued as usize {
            self.cons.push(format!("{}k{}", self.prefix, self.next_k));
            self.next_k += 1;
        }
    }

    fn ent(&self, e: EntityId) -> String {
        self.ents.get(e.0 as usize).cloned().unwrap_or_default()
    }
}

// VUGDOCFROMSKETCH (SR516): THE sketch_core -> text constraint map is doc_core's `sketch_cons` / `sketch_pref`; the
// names `journal::cons` / `journal::pref` stay for their callers.
pub use doc_core::{sketch_cons as cons, sketch_pref as pref};

// VUGDOCFROMSKETCH (SR516): the open sketch names its slots for doc_core's one writer (`from_sketch`).
impl SketchNames for Open {
    fn sketch(&self) -> String {
        self.sketch.clone()
    }
    fn entity(&self, slot: EntityId) -> String {
        self.ent(slot)
    }
    fn constraint(&self, id: ConstraintId) -> String {
        self.cons.get(id.0 as usize).cloned().unwrap_or_default()
    }
}

/// The face's sketch statements: the sketch on the face's plane, every live entity in face-id order, every live
/// constraint below `issued` in id order.
fn write_face(open: &Open, f: &SketchFace, out: &mut Vec<Stmt>) {
    // VUGDOCFROMSKETCH (SR516): doc_core's one writer, named by the open sketch's slot maps.
    let v3 = |p: brep_core::Vec3| [p.x, p.y, p.z];
    out.extend(doc_core::from_sketch(&f.sketch, (v3(f.plane.o), v3(f.plane.z), v3(f.plane.x)), f.issued, open));
}

/// A face's sketch alone as a document (sketch `s`, `e<n>` / `k<n>` by face id): the text a proposal names its
/// references in (VUGFACEPHOTO's `photo::doc_of` retires onto this at the fold).
pub fn sketch_doc(face: &SketchFace) -> Doc {
    // VUGDOCFROMSKETCH (SR516): `PlainNames` is exactly `Open::fresh("s")` + `name_slots` (`s` / `e<slot>` / `k<id>`).
    let v3 = |p: brep_core::Vec3| [p.x, p.y, p.z];
    let mut doc = Doc::new(Tol::DEFAULT);
    doc.stmts = doc_core::from_sketch(&face.sketch, (v3(face.plane.o), v3(face.plane.z), v3(face.plane.x)), face.issued, &PlainNames);
    doc
}

/// The first id `f(n)` no statement holds (one namespace).
fn free(stmts: &[Stmt], f: impl Fn(u32) -> String) -> String {
    (0u32..).map(f).find(|id| !stmts.iter().any(|s| s.id() == Some(id.as_str()))).unwrap_or_default()
}

fn sketch_id(j: u32) -> String {
    if j == 0 { FIRST_SKETCH.to_string() } else { format!("s{j}") }
}

/// The open sketch: the LAST sketch statement, when no extrude / revolve names it (its statements are the document's
/// tail: a sketch opens only after the previous one closed with its feature).
fn open_sketch(doc: &Doc) -> Option<usize> {
    let j = doc.stmts.iter().rposition(|s| matches!(s, Stmt::Sketch { .. }))?;
    let id = doc.stmts[j].id()?;
    let used = doc.stmts.iter().any(|s| matches!(s, Stmt::Extrude { sketch, .. } | Stmt::Revolve { sketch, .. } if sketch == id));
    if used { None } else { Some(j) }
}

/// What a regenerate gives: the face (the open sketch, if any) and the body (the solids, if any) for the design, and
/// the journal's open-sketch maps and frozen count.
pub struct Regen {
    pub face: Option<SketchFace>,
    pub body: Option<Body>,
    open: Option<Open>,
    closed: usize,
    /// VUGFACEJOURNALSOLIDFAULT (SR572): the replay failures no solid reads (an Op, an unnamed sketch), carried.
    pub faults: Vec<doc_core::Failure>,
}

/// Regenerate the design from `doc` through doc_core's `replay`: a failure on a statement a solid reads (SR565's ONE rule,
/// deviation.rs `split_faults` over [`solid_stmts`]) is `Err("line N: <fault> <id>")` and nothing is built; every other
/// failure is carried in `Regen::faults` (VUGFACEJOURNALSOLIDFAULT, SR572); else the solids become the Body and the open sketch a SketchFace (its plane by `Frame::new`, its
/// origin the point fixed at (0, 0), its dimensions re-placed beside their feet).
pub fn regenerate(doc: &Doc) -> Result<Regen, String> {
    let rep = doc_core::replay(doc, doc.tol);
    let (on_solid, faults) = hold(crate::deviation::split_faults(doc, rep.failures.clone())); // VUGFACEJOURNALSOLIDFAULT (SR572): only a solid's failure refuses; VUGFACEJOURNALSOLIDFAULTFIX (SR598): ONE held solid fault joins the carried
    if let Some(f) = on_solid.first() {
        return Err(format!("line {}: {:?} {}", f.line, f.fault, f.id));
    }
    let breps = live_breps(&standing(doc, &faults), &rep.solids); // VUGFACETREEFILLET (SR518): an edit's solid stands in its on solid's place; VUGFACEJOURNALSOLIDFAULTFIX (SR598): the held chain dropped
    let body = if breps.is_empty() { None } else { Some(Body::from_breps(breps, doc.tol)?) };
    let Some(j) = open_sketch(doc) else {
        return Ok(Regen { face: None, body, open: None, closed: doc.stmts.len(), faults });
    };
    let Stmt::Sketch { id, o, z, x } = &doc.stmts[j] else { return Err(format!("line {}: not a sketch", doc.line(j))) };
    let v = |a: &[f64; 3]| brep_core::Vec3::new(a[0], a[1], a[2]);
    let plane = Frame::new(v(o), v(z), v(x)).map_err(|e| format!("line {}: {e:?} {id}", doc.line(j)))?;
    let sk = rep.sketches.iter().find(|s| s.id == *id).map(|s| s.sketch.clone()).ok_or_else(|| format!("line {}: Diverged {id}", doc.line(j)))?;
    let (mut ents, mut kons, mut origin) = (Vec::new(), Vec::new(), None);
    for s in &doc.stmts[j + 1..] {
        match s {
            Stmt::Point { id: e, sketch, .. } | Stmt::Line { id: e, sketch, .. } | Stmt::Circle { id: e, sketch, .. } | Stmt::Arc { id: e, sketch, .. }
                if sketch == id =>
            {
                ents.push(e.clone())
            }
            Stmt::Constraint { id: k, sketch, c } if sketch == id => {
                if let Cons::Fix(PRef::Point(p), at) = c {
                    if origin.is_none() && at[0] == 0.0 && at[1] == 0.0 {
                        origin = Some(p.clone());
                    }
                }
                kons.push(k.clone());
            }
            _ => {}
        }
    }
    let origin = origin.and_then(|p| ents.iter().position(|e| *e == p)).unwrap_or(0);
    let mut face = SketchFace::new(plane);
    face.sketch = sk;
    face.origin = EntityId(origin as u32);
    face.issued = kons.len() as u32;
    let dims: Vec<Dimension> = (0..face.issued)
        .filter_map(|i| {
            let dim = Dim::of(face.sketch.constraint(ConstraintId(i))?)?;
            let at = dim.foot(&face.sketch, Vec2::new(1e3, 1e3))?;
            Some(Dimension { constraint: ConstraintId(i), dim, anchor: Vec2::new(at.x + 3.0, at.y + 3.0) })
        })
        .collect();
    face.dims = dims;
    face.settle();
    let prefix = if id == FIRST_SKETCH { String::new() } else { id.clone() };
    let next = |names: &[String], tag: char| {
        names.iter().filter_map(|n| n.strip_prefix(prefix.as_str())?.strip_prefix(tag)?.parse::<u32>().ok()).max().map_or(0, |m| m + 1)
    };
    let (next_e, next_k) = (next(&ents, 'e'), next(&kons, 'k'));
    let open = Open { sketch: id.clone(), prefix: prefix.clone(), ents, cons: kons, next_e, next_k };
    Ok(Regen { face: Some(face), body, open: Some(open), closed: j, faults })
}

/// The value a row edits, as shown: a dimension constraint's mm (an angle in degrees), an extrude's length, a
/// revolve's angle in degrees, a fillet's radius, a chamfer's `d1` (VUGFACETREEEDITR, SR528); None for a row without one.
pub fn value(s: &Stmt) -> Option<f64> {
    match s {
        Stmt::Constraint { c, .. } => match c {
            Cons::Distance(_, _, v) | Cons::DistancePointLine(_, _, v) | Cons::Radius(_, v) | Cons::Diameter(_, v) => Some(*v),
            Cons::Angle(_, _, t) => Some(t.abs().to_degrees()),
            _ => None,
        },
        Stmt::Extrude { length, .. } => Some(*length),
        Stmt::Revolve { angle, .. } => Some(angle.to_degrees()),
        Stmt::Fillet { r, .. } => Some(*r),
        Stmt::Chamfer { d1, .. } => Some(*d1),
        _ => None,
    }
}

/// The statement with its value replaced by `v` (as [`value`] shows it; an angle keeps its sign; a chamfer takes `v`
/// for both distances, the edge tool's one-value rule).
fn with_value(s: &Stmt, v: f64) -> Option<Stmt> {
    let mut s = s.clone();
    match &mut s {
        Stmt::Constraint { c, .. } => match c {
            Cons::Distance(_, _, x) | Cons::DistancePointLine(_, _, x) | Cons::Radius(_, x) | Cons::Diameter(_, x) => *x = v,
            Cons::Angle(_, _, t) => {
                let sign = if *t < 0.0 { -1.0 } else { 1.0 };
                *t = v.to_radians() * sign;
            }
            _ => return None,
        },
        Stmt::Extrude { length, .. } => *length = v,
        Stmt::Revolve { angle, .. } => *angle = v.to_radians(),
        Stmt::Fillet { r, .. } => *r = v,
        Stmt::Chamfer { d1, d2, .. } => {
            *d1 = v;
            *d2 = v;
        }
        _ => return None,
    }
    Some(s)
}

/// The document, its snapshots and the panel.
#[derive(Clone, Debug)]
pub struct Journal {
    /// The face's truth.
    pub doc: Doc,
    /// Statements before this index are frozen (closed sketches and their features); the open sketch is the rest.
    closed: usize,
    open: Option<Open>,
    undo: Vec<Doc>,
    redo: Vec<Doc>,
    /// The panel is shown (`t`).
    pub panel: bool,
    /// The panel's cursor row (a statement index).
    pub cursor: usize,
    /// A row value being typed (Enter on a row with a value).
    pub edit: Option<String>,
    /// The last panel message: a refusal names its line (`line N: ...`), a delete names what went.
    pub note: Option<String>,
    // VUGFACESAVE (SR534): the text last written or read (None: never saved, dirty iff there are statements).
    saved: Option<String>,
    /// VUGFACESAVE (SR534): the corner line: `saved <name>`, or the write error by name.
    pub disk: Option<Result<String, String>>,
    /// VUGFACESAVEAS (SR539): the Save As field while it is open (Cmd+Shift+S; lib.rs `Viewer::save_as_key`).
    pub save_as: Option<SaveAs>,
    /// VUGFACEJOURNALSOLIDFAULT (SR572): the last regenerate's carried failures (no solid reads them), marked in the panel.
    pub faults: Vec<doc_core::Failure>,
    /// VUGFACEJOURNALFAULTFIX (SR578): the faulted statement id whose offered fix Escape declined (cleared by a commit).
    pub declined: Option<String>,
    /// VUGFACEJOURNALFAULTFIXMANY (SR584): the machines beside the part (lib.rs `open_vug` reads doc_host's shelf), offered
    /// on a NoMachine fault when the undo history holds none; the journal opens no file.
    pub shelf: Vec<Stmt>,
    /// VUGFACEJOURNALFAULTFIXMANY (SR584): the faulted statement id and the choice Tab picked on its fix card (cleared by a commit).
    pub pick: Option<(String, usize)>,
}

impl Default for Journal {
    fn default() -> Journal {
        Journal { doc: Doc::new(Tol::DEFAULT), closed: 0, open: None, undo: Vec::new(), redo: Vec::new(), panel: false, cursor: 0, edit: None, note: None, saved: None, disk: None, save_as: None, faults: Vec::new(), declined: None, shelf: Vec::new(), pick: None }
    }
}

impl Journal {
    /// The snapshot counts (undo, redo).
    pub fn depth(&self) -> (usize, usize) {
        (self.undo.len(), self.redo.len())
    }

    /// The panel rows: the writer's lines (the header skipped), upper-cased (the raster font's case).
    pub fn rows(&self) -> Vec<String> {
        doc_core::write(&self.doc).lines().skip(1).map(str::to_uppercase).collect()
    }

    /// A committed face action: the open sketch re-written from `face` behind the frozen statements, and a committed
    /// `pull` appended as `extrude x<n>` (closing the sketch). A changed document is a snapshot.
    pub fn record(&mut self, face: Option<&SketchFace>, pull: Option<&Pull>) {
        let Some(f) = face else { return };
        let mut stmts: Vec<Stmt> = self.doc.stmts[..self.closed.min(self.doc.stmts.len())].to_vec();
        if self.open.is_none() {
            let id = free(&stmts, sketch_id);
            self.open = Some(Open::fresh(id));
        }
        let Some(open) = self.open.as_mut() else { return };
        open.name_slots(f);
        write_face(open, f, &mut stmts);
        let mut closing = false;
        if let Some(p) = pull {
            if let Some(src) = p.profile.outer.edges.first().map(|e| e.src()) {
                let z = [p.plane.z.x, p.plane.z.y, p.plane.z.z];
                let dir = if p.distance < 0.0 { z.map(|c| -c) } else { z };
                let id = free(&stmts, |n| format!("x{n}"));
                stmts.push(Stmt::Extrude { id, sketch: open.sketch.clone(), outer: open.ent(src), dir, length: p.distance.abs() });
                closing = true;
            }
        }
        if closing {
            self.closed = stmts.len();
            self.open = None;
        }
        self.commit(Doc { tol: self.doc.tol, stmts, lines: Vec::new() });
    }

    fn commit(&mut self, new: Doc) {
        if new == self.doc {
            return;
        }
        let old = std::mem::replace(&mut self.doc, new);
        self.undo.push(old);
        if self.undo.len() > UNDO_DEPTH {
            self.undo.remove(0);
        }
        self.redo.clear();
        self.cursor = self.doc.stmts.len().saturating_sub(1);
        self.note = None; self.declined = None; self.pick = None; // VUGFACEJOURNALFAULTFIXMANY (SR584): the card's pick asked again; VUGFACEJOURNALFAULTFIX (SR578): a new document, the offers asked again
    }

    /// A history edit: regenerate `cand`, and only then make it the document (a snapshot). VUGINTENTUNDOSET (SR563): also
    /// the photo road's accepted statement set (`photo::enter_set`), N statements in ONE snapshot (one `u`).
    pub fn adopt(&mut self, cand: Doc) -> Result<Regen, String> {
        let mut r = regenerate(&cand)?;
        let cursor = self.cursor;
        self.commit(cand);
        self.open = r.open.take();
        self.closed = r.closed; self.faults = r.faults.clone(); // VUGFACEJOURNALSOLIDFAULT (SR572): the carried failures
        self.cursor = cursor.min(self.doc.stmts.len().saturating_sub(1));
        Ok(r)
    }

    /// `u` (back) / `U`: the previous (next) snapshot regenerated; None with nothing to step to, or with the failure
    /// in the note (the snapshot stays where it was).
    pub fn step(&mut self, back: bool) -> Option<Regen> {
        let target = if back { self.undo.pop()? } else { self.redo.pop()? };
        match regenerate(&target) {
            Ok(mut r) => {
                let cur = std::mem::replace(&mut self.doc, target);
                if back {
                    self.redo.push(cur);
                } else {
                    self.undo.push(cur);
                }
                self.open = r.open.take();
                self.closed = r.closed; self.faults = r.faults.clone(); // VUGFACEJOURNALSOLIDFAULT (SR572): the carried failures
                self.cursor = self.doc.stmts.len().saturating_sub(1);
                self.note = None;
                Some(r)
            }
            Err(e) => {
                if back {
                    self.undo.push(target);
                } else {
                    self.redo.push(target);
                }
                self.note = Some(e);
                None
            }
        }
    }

    /// Delete statement `i` and its dependants: doc_core's reader refuses a reference to a removed id
    /// (`UnknownRef`, by line) and replay names a statement that waited on one (`Upstream`, by line); each is removed
    /// until both are clean. Another refusal keeps everything and names its line. The origin point stays.
    pub fn delete(&mut self, i: usize) -> Result<Regen, String> {
        let row = self.doc.stmts.get(i).ok_or("no row")?;
        if let Stmt::Point { id, .. } = row {
            let fixed = self.doc.stmts.iter().any(|s| matches!(s, Stmt::Constraint { c: Cons::Fix(PRef::Point(p), at), .. } if p == id && at[0] == 0.0 && at[1] == 0.0));
            if fixed {
                return Err(format!("line {}: the origin stays", self.doc.line(i)));
            }
        }
        let mut cand = self.doc.clone();
        cand.lines.clear();
        cand.stmts.remove(i);
        for _ in 0..=self.doc.stmts.len() {
            match self.doc.reread(&doc_core::write(&cand)) { // VUGMAKEMACHINELIBHELD (SR556): the library the part holds resolves, no file
                Err(r) if matches!(r.what, What::UnknownRef(_)) && r.line >= 2 && ((r.line - 2) as usize) < cand.stmts.len() => {
                    cand.stmts.remove((r.line - 2) as usize);
                    continue;
                }
                Err(r) => return Err(format!("line {}: {:?}", r.line, r.what)),
                Ok(_) => {}
            }
            let rep = doc_core::replay(&cand, cand.tol);
            match rep.failures.iter().find(|f| matches!(f.fault, Fault::Upstream(_))) {
                Some(f) if f.line >= 2 && ((f.line - 2) as usize) < cand.stmts.len() => {
                    cand.stmts.remove((f.line - 2) as usize);
                }
                _ => break,
            }
        }
        let gone: Vec<String> = doc_core::diff(&self.doc, &cand)
            .entries
            .into_iter()
            .filter_map(|e| match e {
                Entry::Removed { id, .. } => Some(id),
                _ => None,
            })
            .collect();
        let r = self.adopt(cand)?;
        self.note = Some(format!("deleted {}", gone.join(" ")));
        Ok(r)
    }

    /// Enter on an open row edit: the typed value replaces the row's, through `regenerate` (a refusal names its line
    /// and nothing changes). A chamfer row's `d1,d2` sets both (VUGFACETREEEDITR, SR528).
    fn commit_value(&mut self) -> Result<Regen, String> {
        let buf = self.edit.take().unwrap_or_default();
        let i = self.cursor;
        let (v, second) = parse_pair(&buf).ok_or_else(|| format!("line {}: Invalid", self.doc.line(i)))?;
        let mut s = self.doc.stmts.get(i).and_then(|s| with_value(s, v)).ok_or_else(|| format!("line {}: no value", self.doc.line(i)))?;
        match (&mut s, second) {
            (Stmt::Chamfer { d2, .. }, Some(b)) => *d2 = b,
            (_, Some(_)) => return Err(format!("line {}: Invalid", self.doc.line(i))),
            _ => {}
        }
        self.replace(i, s) // VUGFACEJOURNALFAULTFIXREF (SR590): THE statement replace, the fix road's too
    }
}

/// The view's key, before the sketch face's: `u` / `U` undo / redo, `t` the panel; with the panel shown Up / Down,
/// Delete / BackSpace (the cursor row) and Enter (its value; then digits, a chamfer's one comma, Enter, Esc). None while a pull, a dimension
/// edit or a gesture is open, and for every other key.
pub fn key(d: &mut Design, k: &str) -> Option<bool> {
    if gesturing(d) {
        return None;
    }
    use crate::sketch::FieldKey;
    let fk = FieldKey::of(k); // VUGFACEFIELDKEYSREST (SR605): the one key-name table, read once
    let enter = fk == Some(FieldKey::Enter);
    let back = fk == Some(FieldKey::Backspace);
    let ch = crate::sketch::field_char(k); // VUGFACEFIELDKEYSREST (SR605): the one typed char
    let j = &mut d.journal;
    let pair = matches!(j.doc.stmts.get(j.cursor), Some(Stmt::Chamfer { .. })); // VUGFACETREEEDITR (SR528): a chamfer row takes d1,d2
    let outcome: Result<Regen, String> = if let Some(buf) = j.edit.as_mut() {
        if enter {
            j.commit_value()
        } else if fk == Some(FieldKey::Escape) { // VUGFACEFIELDKEYSREST (SR605)
            j.edit = None;
            return Some(true);
        } else if type_pair(buf, ch, back, pair) {
            return Some(true);
        } else {
            j.edit = None;
            return None;
        }
    } else {
        match k {
            "u" | "U" => {
                let had = j.note.clone();
                match j.step(k == "u") {
                    Some(r) => Ok(r),
                    None => return Some(j.note != had),
                }
            }
            "t" => {
                j.panel = !j.panel;
                return Some(true);
            }
            _ if !j.panel => return None,
            _ if fk == Some(FieldKey::Up) => { // VUGFACEFIELDKEYSREST (SR605): the table's Up / Down / Delete / Escape
                let c = j.cursor;
                j.cursor = c.saturating_sub(1);
                return Some(c != j.cursor);
            }
            _ if fk == Some(FieldKey::Down) => {
                let c = j.cursor;
                j.cursor = (c + 1).min(j.doc.stmts.len().saturating_sub(1));
                return Some(c != j.cursor);
            }
            _ if fk == Some(FieldKey::Delete) => j.delete(j.cursor),
            _ if back => j.delete(j.cursor),
            _ if enter && j.offered().is_some() => j.accept_fix(), // VUGFACEJOURNALFAULTFIX (SR578): Enter takes the fix offered on the faulted row
            _ if fk == Some(FieldKey::Escape) && j.offered().is_some() => {
                j.decline_fix(); // VUGFACEJOURNALFAULTFIX (SR578): Escape declines it
                return Some(true);
            }
            "Tab" | "\t" if j.choosing_fix() => return Some(j.next_fix()), // VUGFACEJOURNALFAULTFIXMANY (SR584): Tab walks the fix card's choices
            _ if enter => {
                match j.doc.stmts.get(j.cursor).and_then(value) {
                    Some(_) => {
                        j.edit = Some(String::new());
                        j.note = None;
                    }
                    None => j.note = Some(format!("line {}: no value", j.doc.line(j.cursor))),
                }
                return Some(true);
            }
            _ => return None,
        }
    };
    match outcome {
        Ok(r) => {
            d.face = r.face;
            d.body = r.body;
            d.pull = None;
            d.refusal = None;
        }
        Err(e) => d.journal.note = Some(e),
    }
    Some(true)
}

/// The panel: the right quarter of the frame, a row per statement (the cursor row tinted, an edit shown as
/// `<verb> <id> = <typed>`), the note at the bottom (a refusal in the refusal colour).
pub fn overlay(view: &View, fr: &mut Raster) {
    disk_overlay(view, fr); save_as_overlay(view, fr); let j = &view.design.journal; // VUGFACESAVEAS (SR539): the Save As field; VUGFACESAVE (SR534): the save's corner line, panel or not
    if !j.panel {
        return;
    }
    let h = fr.height as f32;
    let x0 = panel_x0(fr.width); // VUGFACEJOURNALFAULTFIX (SR578): the one panel edge (deviation.rs corner_origin reads it)
    // VUGFACEGDTREPORTOPEN (SR581): the backdrop and the rows through THE panel painter (the report sheet's too); the
    // journal's style: a faulted row in the refusal colour (SR572), the cursor's band, an edit as `<verb> <id> = <typed>`.
    let rows = j.rows();
    let fit = panel_fit(fr.height);
    let first = j.cursor.saturating_sub(fit / 2).min(rows.len().saturating_sub(fit));
    let cols = panel_cols(fr.width);
    let clip = |s: &str| s.chars().take(cols).collect::<String>();
    paint_panel(fr, &rows, first, &|i, row| {
        let mut col = if j.faulted(i) { rgba(REFUSED) } else { rgba(INK) };
        let mut text = row.to_string();
        if i == j.cursor {
            if let Some(buf) = &j.edit {
                let head = text.split_whitespace().take(2).collect::<Vec<_>>().join(" ");
                text = format!("{head} = {buf}");
                col = rgba(ACTIVE);
            }
        }
        (text, col, i == j.cursor)
    });
    fix_overlay(j, fr, x0, h, &clip); // VUGFACEJOURNALFAULTFIX (SR578): the offered fix above the note
    if let Some(n) = &j.note_row() { // VUGFACEJOURNALHOLDNOFIXWORD (SR630): the note row's one sayer (`held=<ids> no fix` when no held root has a fix)
        let col = if n.starts_with("line ") { rgba(REFUSED) } else { rgba(INK) };
        raster::text(fr, &clip(&n.to_uppercase()), x0 + 4.0, h - ROW_PX, col);
    }
}

// ---- VUGFACETREEFILLET (SR518): an edge edit enters the document ----

/// The Body's solids as document ids, in Body order: THE body-index rule the face (fillet.rs, `Picked::brep`) and
/// [`regenerate`] share. An extrude / revolve appends its id (the pull's brep is appended, its statement too); a
/// fillet / chamfer replaces the id equal to its `on` in place (the face's edit replaces `breps[k]`; replay keeps the
/// `on` solid and pushes the edit's at the end, so the order is the document's, not replay's).
pub(crate) fn live_solids(doc: &Doc) -> Vec<String> {
    let mut ids: Vec<String> = Vec::new();
    for s in &doc.stmts {
        match s {
            Stmt::Extrude { id, .. } | Stmt::Revolve { id, .. } => ids.push(id.clone()),
            Stmt::Fillet { id, on, .. } | Stmt::Chamfer { id, on, .. } => {
                if let Some(slot) = ids.iter_mut().find(|i| i.as_str() == on.as_str()) {
                    *slot = id.clone();
                }
            }
            _ => {}
        }
    }
    ids
}

/// The replayed Breps in Body order ([`live_solids`]): each id's LAST solid (as replay's `edit_step` reads its `on`).
fn live_breps(doc: &Doc, solids: &[doc_core::SolidOut]) -> Vec<brep_core::Brep> {
    live_outs(doc, solids).into_iter().map(|o| o.brep.clone()).collect() // VUGFACEDEVIATIONLIVE (SR558): the lookup is live_outs'
}

// ---- VUGFACEDEVIATIONLIVE (SR558): the live solids and the solid statements, for the deviation map too ----

/// The replayed solids in Body order ([`live_solids`]): each live id's LAST solid (as replay's `edit_step` reads its
/// `on`). [`live_breps`] (the Body) and deviation.rs `design` (the measured design) both read it.
pub(crate) fn live_outs<'a>(doc: &Doc, solids: &'a [doc_core::SolidOut]) -> Vec<&'a doc_core::SolidOut> {
    live_solids(doc).iter().filter_map(|id| solids.iter().rev().find(|o| o.id == *id)).collect()
}

/// The statements doc_core's `replay` feeds into solids, in document order: every extrude / revolve and fillet /
/// chamfer, and each sketch an extrude / revolve names with its entities and constraints (its solve, its profiles and
/// its frame). An Op (replay feeds it to the Program only), the machine, a scan and a sketch no feature names are not:
/// an edit of those changes no solid (deviation.rs `follow` re-measures only when this list, or the Tol, changes).
pub fn solid_stmts(doc: &Doc) -> Vec<Stmt> {
    let named: Vec<&str> = doc
        .stmts
        .iter()
        .filter_map(|s| match s {
            Stmt::Extrude { sketch, .. } | Stmt::Revolve { sketch, .. } => Some(sketch.as_str()),
            _ => None,
        })
        .collect();
    doc.stmts
        .iter()
        .filter(|s| match s {
            Stmt::Extrude { .. } | Stmt::Revolve { .. } | Stmt::Fillet { .. } | Stmt::Chamfer { .. } => true,
            Stmt::Sketch { id: sk, .. }
            | Stmt::Point { sketch: sk, .. }
            | Stmt::Line { sketch: sk, .. }
            | Stmt::Circle { sketch: sk, .. }
            | Stmt::Arc { sketch: sk, .. }
            | Stmt::Constraint { sketch: sk, .. } => named.contains(&sk.as_str()),
            _ => false,
        })
        .cloned()
        .collect()
}

impl Journal {
    /// A committed edge edit of the face: `stmt` (a `Fillet` / `Chamfer`, its `id` and `on` left empty) gets `on` =
    /// the document id of the Body's solid `brep` ([`live_solids`]) and a free id (`f<n>` / `c<n>`), and is inserted
    /// after the frozen features (an open sketch stays the tail) as a snapshot; the cursor moves to its row. Returns
    /// the id; None when the Body's solid is not the document's (a body set from outside) or `stmt` is no edit.
    pub fn record_edit(&mut self, brep: u32, stmt: Stmt) -> Option<String> {
        let on = live_solids(&standing(&self.doc, &self.faults)).get(brep as usize)?.clone(); // VUGFACEJOURNALSOLIDFAULTFIX (SR598): the Body's index rule over the standing document
        let at = self.closed.min(self.doc.stmts.len());
        let mut stmts = self.doc.stmts.clone();
        let mut stmt = stmt;
        let new_id = match &stmt {
            Stmt::Fillet { .. } => free(&stmts, |n| format!("f{n}")),
            Stmt::Chamfer { .. } => free(&stmts, |n| format!("c{n}")),
            _ => return None,
        };
        match &mut stmt {
            Stmt::Fillet { id, on: o, .. } | Stmt::Chamfer { id, on: o, .. } => {
                *id = new_id.clone();
                *o = on;
            }
            _ => return None,
        }
        stmts.insert(at, stmt);
        self.closed = at + 1;
        self.commit(Doc { tol: self.doc.tol, stmts, lines: Vec::new() });
        self.cursor = at;
        Some(new_id)
    }
}

// ---- VUGFACETREEEDITR (SR528): the fillet / chamfer row's value — THE pair road (the edge tool's and the panel's) ----

/// A value buffer's key: with `pair` (a chamfer) one `,` after a value starts `d2`, and Backspace over a trailing `,`
/// removes it; every other key is sketch.rs `type_into` on the segment after the comma (the whole text without one).
/// False for a key the buffer does not take (a `,` without `pair` included). fillet.rs's tool and the panel share it.
pub(crate) fn type_pair(buf: &mut String, ch: Option<char>, back: bool, pair: bool) -> bool {
    if ch == Some(',') {
        if pair && !buf.is_empty() && !buf.contains(',') {
            buf.push(',');
        }
        return pair;
    }
    if back && buf.ends_with(',') {
        buf.pop();
        return true;
    }
    let at = buf.rfind(',').map_or(0, |i| i + 1);
    let mut seg = buf[at..].to_string();
    if !type_into(&mut seg, ch, back) {
        return false;
    }
    buf.truncate(at);
    buf.push_str(&seg);
    true
}

/// A typed value or pair: `v` or `v,w` as f64s (the second None when there is no comma); None for anything else.
pub(crate) fn parse_pair(buf: &str) -> Option<(f64, Option<f64>)> {
    let mut it = buf.split(',');
    let a = it.next()?.parse::<f64>().ok()?;
    let b = match it.next() {
        Some(t) => Some(t.parse::<f64>().ok()?),
        None => None,
    };
    if it.next().is_some() {
        return None;
    }
    Some((a, b))
}

// ---- VUGFACESAVE (SR534): the save road's document side ----

/// A pull, a dimension edit or a gesture is open: the tree's keys wait (`key`'s guard).
fn gesturing(d: &Design) -> bool {
    d.pull.is_some() || d.face.as_ref().is_some_and(|f| f.edit.is_some() || f.gesture.is_some())
}

/// [`gesturing`], or a row edit is open: a plain `s` belongs to the open edit (the save key in lib.rs).
pub fn busy(d: &Design) -> bool {
    gesturing(d) || d.journal.edit.is_some()
}

impl Journal {
    /// The document differs from the text last written or read (never saved: it holds a statement).
    pub fn dirty(&self) -> bool {
        match &self.saved {
            Some(t) => *t != doc_core::write(&self.doc),
            None => !self.doc.stmts.is_empty(),
        }
    }

    /// `text` (doc_core's writer's output) is on disk now.
    pub fn mark_saved(&mut self, text: String) {
        self.saved = Some(text);
    }

    /// An opened document: regenerated first (a replay failure names its line and nothing changes), then it is
    /// the face's truth with no snapshots, and clean (the saved text is the writer's, so comments in the file do
    /// not make it dirty).
    pub fn load(&mut self, doc: Doc) -> Result<Regen, String> {
        let mut r = regenerate(&doc)?;
        self.saved = Some(doc_core::write(&doc));
        self.doc = doc;
        self.open = r.open.take();
        self.closed = r.closed; self.faults = r.faults.clone(); // VUGFACEJOURNALSOLIDFAULT (SR572): the carried failures
        self.undo.clear();
        self.redo.clear();
        self.cursor = self.doc.stmts.len().saturating_sub(1); self.to_held(); // VUGFACEJOURNALHOLDMANY (SR609): a held document opens on its first root
        self.edit = None;
        self.note = None;
        Ok(r)
    }
}

/// The save's corner line, bottom right (one row up while the panel's note row is shown): upper-cased, an error in
/// the refusal colour.
fn disk_overlay(view: &View, fr: &mut Raster) {
    let j = &view.design.journal;
    let Some(d) = &j.disk else { return };
    let (text, col) = match d {
        Ok(t) => (t.to_uppercase(), rgba(INK)),
        Err(e) => (e.to_uppercase(), rgba(REFUSED)),
    };
    let (w, h) = (fr.width as f32, fr.height as f32);
    let cols = ((w - 12.0) / 8.0).floor().max(1.0) as usize;
    let text: String = text.chars().take(cols).collect();
    let x = (w - 6.0 - 8.0 * text.chars().count() as f32).max(6.0);
    let y = h - ROW_PX - if j.panel { ROW_PX } else { 0.0 };
    raster::text(fr, &text, x, y, col);
}

// ---- VUGFACESAVEAS (SR539): the Save As field ----

/// The Save As field: the typed path, and whether the existing file it names was refused once (the next Enter
/// overwrites; any edit to the text disarms it).
#[derive(Clone, Debug, Default)]
pub struct SaveAs {
    pub text: String,
    pub armed: bool,
    /// VUGFACESAVEASCARET (SR593): the caret, in chars of `text` (sketch.rs `type_text_at` / `caret_key`).
    pub caret: usize,
}

/// The open field, bottom left, one row above the corner line: `SAVE AS: <TEXT>` with the field's `_` at its caret
/// (upper-cased: the font's case), clipped to the frame's width.
fn save_as_overlay(view: &View, fr: &mut Raster) {
    let j = &view.design.journal;
    let Some(f) = &j.save_as else { return };
    field_line_at(fr, "SAVE AS:", &f.text, f.caret, j.panel); // VUGFACESAVEASCARET (SR593): the caret where it is; VUGFACEGDTREPORTOPEN (SR581): THE field painter, the command line's too
}

// ---- VUGFACEJOURNALSOLIDFAULT (LEDGER SR572): a document whose failures no solid reads opens; a fault line is picked ----
// [`regenerate`] refuses only on a failure SR565's rule puts in a solid's chain (deviation.rs `split_faults` over
// [`solid_stmts`]); every other failure (an Op naming no machine, an unnamed sketch's conflict) is carried in
// `Regen::faults` and `Journal::faults` (set by `adopt` / `step` / `load`, left by `record`), and the panel paints a row
// whose statement id a carried failure names in the refusal colour (by id: a record moves lines, never ids). A click on
// the deviation corner's `fault line N` (deviation.rs `fault_click`) selects line N through the panel's one select road,
// the cursor: the panel's scroll and tint follow it.

impl Journal {
    /// Statement `i` is named by a carried failure (its id; a failure with no id names no row).
    pub fn faulted(&self, i: usize) -> bool {
        let Some(id) = self.doc.stmts.get(i).and_then(Stmt::id) else { return false };
        self.faults.iter().any(|f| !f.id.is_empty() && f.id == id)
    }

    /// Select the statement on document line `line`: the panel shown, its cursor on that row, a row edit closed. False
    /// (nothing changes) when no statement is on that line.
    pub fn select_line(&mut self, line: u32) -> bool {
        let Some(i) = (0..self.doc.stmts.len()).find(|&i| self.doc.line(i) == line) else { return false };
        self.cursor = i;
        self.panel = true;
        self.edit = None;
        true
    }
}

// ---- VUGFACEJOURNALFAULTFIX (LEDGER SR578): a fix offered on the faulted line, entered only on the person's key ----
// With the panel shown and its cursor on a row a carried failure names ([`Journal::faulted`]), [`Journal::offered`] is the
// ONE unambiguous fix for that failure, computed on demand from the document, the carried failures and the undo
// snapshots (nothing cached): `NoMachine` (an Op) offers the ONE distinct machine statement the undo snapshots hold (a
// document with a NoMachine fault holds none: doc_core's `machine_of` reads the whole document and the reader refuses a
// second machine and an orphan axis / tool), inserted as a statement (its held library with it) at the first Op's index;
// `Conflicting` (a constraint of a sketch no feature names) offers removing the NEWEST `fix` among that sketch's
// conflicting constraints, never the origin's (at [0 0]). Every other failure offers nothing (a choice: owed
// VUG-FACE-JOURNAL-FAULT-FIX-MANY). Enter enters it through the journal's existing roads, [`Journal::adopt`] (the
// insert) or [`Journal::delete`] (the removal), each ONE snapshot, so one `u` takes it back; Escape declines it until
// the next commit. The photo road's Offer is not used: it needs an open photo and judges against its measurement.

/// How an offered fix enters the document.
#[derive(Clone, Debug, PartialEq)]
pub enum FixRoad {
    /// The statement inserted at this index, through [`Journal::adopt`].
    Insert(usize, Stmt),
    /// The statement at this index removed, through the panel's [`Journal::delete`].
    Remove(usize),
    /// VUGFACEJOURNALFAULTFIXREF (SR590): the statement at this index replaced, through [`Journal::replace`].
    Replace(usize, Stmt),
}

/// A fix offered on a faulted row: the document line it is offered on, its text (the writer's line, or `remove <id>`)
/// and its road.
#[derive(Clone, Debug, PartialEq)]
pub struct Fix {
    pub line: u32,
    pub text: String,
    pub road: FixRoad,
}

/// The panel's left edge on a frame `width` wide: the right quarter is the panel ([`overlay`]; deviation.rs
/// `corner_origin` moves the corner left of it).
pub fn panel_x0(width: u32) -> f32 {
    (width as f32 * 0.75).floor()
}

/// One statement as the writer writes it (its line, the header dropped).
fn stmt_text(s: &Stmt) -> String {
    let mut d = Doc::new(Tol::DEFAULT);
    d.stmts = vec![s.clone()];
    doc_core::write(&d).lines().nth(1).unwrap_or_default().to_string()
}

impl Journal {
    /// VUGFACEJOURNALFAULTFIXMANY (SR584): the fixes for the carried failure on statement `i` (the table above), several
    /// when the failure has a choice: NoMachine every distinct machine the undo snapshots hold (newest first), else every
    /// machine of the shelf beside the part ([`Journal::shelf`], its id made free); None for a row no failure names, a
    /// failure with nothing to offer.
    fn fix_choices(&self, i: usize) -> Option<Vec<Fix>> {
        let id = self.doc.stmts.get(i)?.id()?;
        let f = self.faults.iter().find(|f| !f.id.is_empty() && f.id == id)?;
        let line = self.doc.line(i);
        match &f.fault {
            Fault::NoMachine => {
                let mut held: Vec<&Stmt> = Vec::new();
                for d in self.undo.iter().rev() {
                    for s in d.stmts.iter().filter(|s| matches!(s, Stmt::Machine(_))) {
                        if !held.contains(&s) {
                            held.push(s);
                        }
                    }
                }
                let mut held: Vec<Stmt> = held.into_iter().cloned().collect();
                if held.is_empty() {
                    held = self.shelf.iter().map(|s| self.shelf_id(s)).collect(); // VUGFACEJOURNALFAULTFIXMANY (SR584): the shelf when the history holds none
                }
                if held.is_empty() {
                    return None;
                }
                let at = self.doc.stmts.iter().position(|s| matches!(s, Stmt::Op { .. }))?;
                Some(held.into_iter().map(|m| Fix { line, text: stmt_text(&m), road: FixRoad::Insert(at, m) }).collect())
            }
            Fault::Conflicting => {
                let Stmt::Constraint { sketch, .. } = &self.doc.stmts[i] else { return None };
                let conflicting = |k: &str| self.faults.iter().any(|f| f.fault == Fault::Conflicting && f.id == k);
                let k = (0..self.doc.stmts.len()).rev().find(|&k| {
                    matches!(&self.doc.stmts[k], Stmt::Constraint { id: kid, sketch: s, c: Cons::Fix(_, at) }
                        if s == sketch && !(at[0] == 0.0 && at[1] == 0.0) && conflicting(kid.as_str()))
                })?;
                let rid = self.doc.stmts[k].id()?;
                Some(vec![Fix { line, text: format!("remove {rid}"), road: FixRoad::Remove(k) }])
            }
            Fault::BadRef { id: bad, kind } => self.ref_fixes(i, bad, *kind, line), // VUGFACEJOURNALFAULTFIXREF (SR590): the live entities of the slot's kind
            Fault::NoProfile { .. } | Fault::NoSuchEdge { .. } | Fault::AmbiguousEdge { .. } if held_roots(&self.faults).iter().take_while(|r| r.as_str() != id).all(|r| !self.fixable(r)) => self.solid_fixes(i, &f.fault, line), // VUGFACEJOURNALSOLIDFAULTFIX (SR598): the loops / the edge names; VUGFACEJOURNALHOLDMANY (SR609): the first held root's card only; VUGFACEJOURNALHOLDREST (SR611): the first held root WITH a fix (no earlier held root has one)
            _ => None,
        }
    }

    /// The fix shown now: the panel shown, no row edit open, the cursor row's fix ([`Journal::fix_for`]) unless Escape
    /// declined it.
    pub fn offered(&self) -> Option<Fix> {
        if !self.panel || self.edit.is_some() {
            return None;
        }
        let id = self.doc.stmts.get(self.cursor)?.id()?;
        if self.declined.as_deref() == Some(id) {
            return None;
        }
        self.fix_for(self.cursor)
    }

    /// Enter on the offered fix: inserted through [`Journal::adopt`] or removed through [`Journal::delete`] (ONE
    /// snapshot either way; a refusal names its line and nothing changes); the note `fixed line N: <text>`.
    fn accept_fix(&mut self) -> Result<Regen, String> {
        let f = self.offered().ok_or("no fix")?;
        let r = match f.road {
            FixRoad::Insert(at, s) => {
                let mut cand = self.doc.clone();
                cand.lines.clear();
                cand.stmts.insert(at, s);
                self.adopt(cand)?
            }
            FixRoad::Remove(k) => self.delete(k)?,
            FixRoad::Replace(k, s) => self.replace(k, s)?, // VUGFACEJOURNALFAULTFIXREF (SR590)
        };
        self.note = Some(format!("fixed line {}: {}", f.line, f.text)); self.to_held(); // VUGFACEJOURNALHOLDMANY (SR609): the next held root's card follows the fix
        Ok(r)
    }

    /// Escape on the offered fix: hidden for that statement until the next commit; the note `declined fix line N`.
    fn decline_fix(&mut self) {
        let Some(f) = self.offered() else { return };
        self.declined = self.doc.stmts.get(self.cursor).and_then(Stmt::id).map(str::to_string);
        self.note = Some(format!("declined fix line {}", f.line));
    }
}

/// The offered fix in the panel: `FIX: <TEXT> (ENTER)` in the accent, on the note row (the row above it while a note is
/// shown), clipped to the panel.
fn fix_overlay(j: &Journal, fr: &mut Raster, x0: f32, h: f32, clip: &dyn Fn(&str) -> String) {
    let Some(f) = j.offered() else { return };
    let y = if j.note_row().is_some() { h - 2.0 * ROW_PX } else { h - ROW_PX }; // VUGFACEJOURNALHOLDNOFIXWORD (SR630): the fix one row above the word too
    let all = j.fixes_for(j.cursor); if all.len() > 1 { return fix_card(j, fr, x0, y, &all, &f, clip); } // VUGFACEJOURNALFAULTFIXMANY (SR584): a choice is a card
    raster::text(fr, &clip(&format!("FIX: {} (ENTER)", f.text.to_uppercase())), x0 + 4.0, y, rgba(ACTIVE));
}

// ---- VUGFACEJOURNALFAULTFIXMANY (LEDGER SR584): a fix with a choice, one card in the panel ----
// SR578's road with several fixes: [`Journal::fix_choices`] lists them (NoMachine: every distinct machine of the undo
// history, newest first, else the shelf beside the part), [`Journal::fix_for`] is the one Tab picked ([`Journal::pick`],
// keyed on the faulted statement, 0 on any other row), and Enter takes it through the unchanged [`Journal::accept_fix`]
// (ONE snapshot); Escape declines the whole card. photo.rs's card road is not used: a card there is a statement SET
// entered whole and judged against a photo's measurement; a fix card is a CHOICE of one with no measurement. A Make
// value has nothing to choose (the row's value is typed); BadRef is SR590's (below); NoProfile / an edge reference sit in
// a solid's chain, so `regenerate` refuses them and the journal never carries one (owed VUG-FACE-JOURNAL-SOLIDFAULT-FIX).

impl Journal {
    /// Every fix for the carried failure on statement `i`, in card order (empty: nothing to offer).
    pub fn fixes_for(&self, i: usize) -> Vec<Fix> {
        self.fix_choices(i).unwrap_or_default()
    }

    /// The fix offered for statement `i`: the choice Tab picked (the first until then; one choice is SR578's one fix).
    pub fn fix_for(&self, i: usize) -> Option<Fix> {
        let all = self.fixes_for(i);
        let k = self.pick_of(i, all.len());
        all.into_iter().nth(k)
    }

    /// The picked index on statement `i`'s card of `n` choices.
    fn pick_of(&self, i: usize, n: usize) -> usize {
        let id = self.doc.stmts.get(i).and_then(Stmt::id);
        match &self.pick {
            Some((p, k)) if n > 0 && Some(p.as_str()) == id => k % n,
            _ => 0,
        }
    }

    /// A card is offered: the panel's offered fix has more than one choice.
    pub fn choosing_fix(&self) -> bool {
        self.offered().is_some() && self.fixes_for(self.cursor).len() > 1
    }

    /// Tab on the offered card: the next choice (wrapping); false when no card is offered.
    fn next_fix(&mut self) -> bool {
        if !self.choosing_fix() {
            return false;
        }
        let n = self.fixes_for(self.cursor).len();
        let k = (self.pick_of(self.cursor, n) + 1) % n;
        let Some(id) = self.doc.stmts.get(self.cursor).and_then(Stmt::id).map(str::to_string) else { return false };
        self.pick = Some((id, k));
        true
    }

    /// A shelf machine with an id free in the document: its own (the library's name), else `<id><n>`.
    fn shelf_id(&self, s: &Stmt) -> Stmt {
        let Stmt::Machine(m) = s else { return s.clone() };
        let id = free(&self.doc.stmts, |n| if n == 0 { m.id.clone() } else { format!("{}{n}", m.id) });
        Stmt::Machine(doc_core::MachineStmt { id, ..m.clone() })
    }
}

/// The panel offers a fix card (photo.rs yields Tab to it).
pub fn choosing(d: &Design) -> bool {
    d.journal.choosing_fix()
}

/// The fix card: a tinted block ending on the fix row `y`: the head `FIX: CHOOSE <k>/<n> (TAB, ENTER)`, then one row per
/// choice, the picked one `> ` in the accent, the others in ink; clipped to the panel.
fn fix_card(j: &Journal, fr: &mut Raster, x0: f32, y: f32, all: &[Fix], f: &Fix, clip: &dyn Fn(&str) -> String) {
    let n = all.len();
    let k = j.pick_of(j.cursor, n);
    let top = y - n as f32 * ROW_PX;
    let w = fr.width as f32;
    raster::tint(fr, &[vec![(x0, top - 2.0), (w, top - 2.0), (w, y + ROW_PX - 2.0), (x0, y + ROW_PX - 2.0)]], rgba(raster::BACKGROUND), 0.9);
    raster::text(fr, &clip(&format!("FIX: CHOOSE {}/{n} (TAB, ENTER)", k + 1)), x0 + 4.0, top, rgba(ACTIVE));
    for (r, c) in all.iter().enumerate() {
        let (mark, col) = if c == f { ("> ", rgba(ACTIVE)) } else { ("  ", rgba(INK)) };
        raster::text(fr, &clip(&format!("{mark}{}", c.text.to_uppercase())), x0 + 4.0, top + (r + 1) as f32 * ROW_PX, col);
    }
}

// ---- VUGFACEGDTREPORTOPEN (LEDGER SR581): THE panel painter and THE field painter ----
// The tree panel's paint was held inside [`overlay`]; [`paint_panel`] is it, handed rows: the journal paints its
// statements through it with its own style, deviation.rs `line_overlay` paints an opened `.vugreport` (the sheet).
// [`field_line_at`] is the Save As field's paint, handed a label and a caret: the face's `:` command line paints through it too.

/// The rows that fit in the panel on a frame `height` tall, above its two foot rows (the fix and the note).
pub(crate) fn panel_fit(height: u32) -> usize {
    ((height as f32 - 2.0 * ROW_PX) / ROW_PX).floor().max(1.0) as usize
}

/// The characters a panel row holds on a frame `width` wide.
pub(crate) fn panel_cols(width: u32) -> usize {
    ((width as f32 - panel_x0(width) - 8.0) / 8.0).floor().max(1.0) as usize
}

/// THE panel painter: the right quarter's backdrop and its rule at [`panel_x0`], then `rows[first..]` one per
/// [`ROW_PX`] from the top, as many as [`panel_fit`] holds, each through `style(i, row)` -> (text, colour, banded: the
/// cursor's tint behind it), clipped to [`panel_cols`].
pub(crate) fn paint_panel(fr: &mut Raster, rows: &[String], first: usize, style: &dyn Fn(usize, &str) -> (String, [u8; 4], bool)) {
    let (w, h) = (fr.width as f32, fr.height as f32);
    let x0 = panel_x0(fr.width);
    raster::tint(fr, &[vec![(x0, 0.0), (w, 0.0), (w, h), (x0, h)]], rgba(raster::BACKGROUND), 0.9);
    raster::line(fr, (x0, 0.0), (x0, h), rgba(INK));
    let cols = panel_cols(fr.width);
    for (k, i) in (first..rows.len().min(first + panel_fit(fr.height))).enumerate() {
        let y = 4.0 + k as f32 * ROW_PX;
        let (text, col, band) = style(i, &rows[i]);
        if band {
            raster::tint(fr, &[vec![(x0, y - 2.0), (w, y - 2.0), (w, y + ROW_PX - 2.0), (x0, y + ROW_PX - 2.0)]], rgba(ACTIVE), 0.25);
        }
        raster::text(fr, &text.chars().take(cols).collect::<String>(), x0 + 4.0, y, col);
    }
}

// ---- VUGFACECOMMANDCARET (LEDGER SR587): the field's caret ----

/// THE field painter (VUGFACESAVEASCARET SR593: `field_line`, its caret-at-the-end caller, retired with its last caller):
/// `<LABEL> <TEXT>` bottom left, one row above the corner line (one more while the panel's note row is shown),
/// upper-cased (the font's case), clipped to the frame's width, in the active colour, with the caret at char `caret` of
/// `text`: the field's `_` at the caret's column — on the text row at the end, one font row lower under the caret's char
/// mid-text (the font's `_` shares the letters' bottom row). The column counts the upper-cased text before the caret; a
/// column past the clip paints no caret.
pub(crate) fn field_line_at(fr: &mut Raster, label: &str, text: &str, caret: usize, panel: bool) {
    let (w, h) = (fr.width as f32, fr.height as f32);
    let cols = ((w - 12.0) / 8.0).floor().max(1.0) as usize;
    let line: String = format!("{label} {}", text.to_uppercase()).chars().take(cols).collect();
    let y = h - 2.0 * ROW_PX - if panel { ROW_PX } else { 0.0 };
    raster::text(fr, &line, 6.0, y, rgba(ACTIVE));
    let n = text.chars().count();
    let before: String = text.chars().take(caret.min(n)).collect();
    let col = label.chars().count() + 1 + before.to_uppercase().chars().count();
    if col < cols {
        let dy = if caret < n { 2.0 } else { 0.0 };
        raster::text(fr, "_", 6.0 + 8.0 * col as f32, y + dy, rgba(ACTIVE));
    }
}

// ---- VUGFACEJOURNALFAULTFIXREF (LEDGER SR590): a BadRef offers the live entities of the kind its slot wanted ----
// doc_core's `Fault::BadRef` names the refused id and the kind its slot wanted (`RefKind`, read from the statement in
// sketch_core's check order). The fixes are the statements of the same sketch BEFORE the faulted one (replay reads in
// document order) of that kind (`RefKind::holds`, THE kind table), not themselves faulted, not already referenced by the
// faulted statement: each is the faulted statement with the refused id re-named (photo.rs `renamed`, on the writer's
// line, read back by `Doc::reread`), entered by [`Journal::replace`] (ONE snapshot). One fix is SR578's; several are
// SR584's card. NoProfile / NoSuchEdge / AmbiguousEdge carry their candidates too (doc_core) but never reach `faults`.

impl Journal {
    /// THE statement replace: statement `i` replaced by `s` through [`Journal::adopt`] (a refusal names its line and
    /// nothing changes). A row value's Enter and a Replace fix both enter here.
    fn replace(&mut self, i: usize, s: Stmt) -> Result<Regen, String> {
        let mut cand = self.doc.clone();
        cand.lines.clear();
        cand.stmts[i] = s;
        self.adopt(cand)
    }

    /// The fixes for statement `i`'s BadRef on `bad` (wanted `kind`), on document line `line`; None with none to offer.
    fn ref_fixes(&self, i: usize, bad: &str, kind: doc_core::RefKind, line: u32) -> Option<Vec<Fix>> {
        let stmt = self.doc.stmts.get(i)?;
        let refs = stmt.refs();
        let sketch = *refs.first()?;
        let faulted = |id: &str| self.faults.iter().any(|f| f.id == id);
        let text = doc_core::write(&self.doc);
        let lines: Vec<&str> = text.lines().collect();
        let own = lines.get(i + 1)?.to_string();
        let mut out = Vec::new();
        for s in &self.doc.stmts[..i] {
            let Some(id) = s.id() else { continue };
            if !kind.holds(s) || s.refs().first() != Some(&sketch) || faulted(id) || refs.contains(&id) {
                continue;
            }
            let new = crate::photo::renamed(&own, &[(bad.to_string(), id.to_string())]);
            let Some(fixed) = self.retyped(i, &text, &new) else { continue }; // VUGFACEJOURNALSOLIDFAULTFIX (SR598): THE reread, lifted
            out.push(Fix { line, text: stmt_text(&fixed), road: FixRoad::Replace(i, fixed) });
        }
        if out.is_empty() { None } else { Some(out) }
    }
}

// ---- VUGFACEPATHBESIDE (LEDGER SR594): THE typed-path rule ----
// Save As's field (lib.rs `save_as_enter`) joined a relative name to the opened file's dir while the `:` line's typed
// `report open <path>` (deviation.rs `Viewer::map_command`) read it from the cwd: one name, two places. [`beside`] is the
// one rule both take, in deviation.rs `report_target`'s order (the journal's part, else a path map's design document).

/// THE typed-path rule (the Save As field and the `:` line's `report open <path>`): an absolute path as typed; a relative
/// one beside the opened document (`Viewer::save_to`, else a path map's design path); with no opened document, as typed
/// (the cwd).
pub fn beside(v: &crate::Viewer, typed: &str) -> std::path::PathBuf {
    let p = std::path::PathBuf::from(typed);
    let opened = v.save_to.as_deref().or_else(|| v.view.deviation.as_ref().and_then(|m| m.design_path.as_deref()));
    match opened.and_then(|o| o.parent()) {
        Some(dir) if p.is_relative() => dir.join(p),
        _ => p,
    }
}

// ---- VUGFACEJOURNALSOLIDFAULTFIX (LEDGER SR598): ONE solid fault is held, its statement unapplied, its fix offered ----
// doc_core's replay already skips a failed feature and keeps building: the failed solid is not built, whatever stands on
// it fails `Upstream(<its id>)`, every other solid is built. SR572's refusal kept the painted Body from being a solid
// stack with a hole nobody named; [`hold`] names it instead when the solid half is ONE root fault whose data a fix
// chooses from (NoProfile: the closed loops; NoSuchEdge / AmbiguousEdge: the `on` solid's resolving edge names) and only
// its `Upstream` chain: those failures join the carried ones (`Journal::faults`, the rows painted by `faulted`), and the
// Body is the solids of the [`standing`] document (the held statements dropped, so a held fillet's `on` solid keeps its
// slot and [`Journal::record_edit`]'s index rule matches the Body). A Conflicting / Diverged / BadRef in a named
// sketch, a Brep refusal (SR528's RadiusTooLarge) still refuse by the first line: one card restores ONE statement in
// ONE snapshot; two or more roots are held together, the card on the first (VUGFACEJOURNALHOLDMANY, SR609, below) that has a fix (VUGFACEJOURNALHOLDREST, SR611).
// The hold is regenerate's, so load / adopt / step share it (an edit that newly breaks an edge name is held with its
// card, not refused). The choices ride SR584's card and SR590's Replace road through [`Journal::retyped`].

type Split = (Vec<doc_core::Failure>, Vec<doc_core::Failure>);

/// deviation.rs `split_faults`'s (solid half, carried) with the solid half moved into the carried (re-sorted by line)
/// when every root is a NoProfile / NoSuchEdge / AmbiguousEdge with an id and every `Upstream` failure chains from a
/// root in line order (VUGFACEJOURNALHOLDMANY, SR609: one root or many); anything else unchanged (the caller refuses
/// on the solid half's first).
pub(crate) fn hold((on_solid, mut carried): Split) -> Split { // VUGFACEDEVIATIONHELD (SR600): the deviation map's road (deviation.rs `held_split`)
    let held = { // VUGFACEJOURNALHOLDMANY (SR609): every root held, each with its own Upstream chain
        let roots: Vec<&doc_core::Failure> = on_solid.iter().filter(|f| !matches!(f.fault, Fault::Upstream(_))).collect();
        let rooted = !roots.is_empty() && roots.iter().all(|r| !r.id.is_empty() && root_kind(&r.fault));
        let mut chain: Vec<&str> = roots.iter().map(|r| r.id.as_str()).collect();
        rooted
            && on_solid.iter().filter(|f| matches!(f.fault, Fault::Upstream(_))).all(|f| match &f.fault {
                Fault::Upstream(u) if !f.id.is_empty() && chain.contains(&u.as_str()) => {
                    chain.push(f.id.as_str());
                    true
                }
                _ => false,
            })
    };
    if !held {
        return (on_solid, carried);
    }
    carried.extend(on_solid);
    carried.sort_by_key(|f| f.line);
    (Vec::new(), carried)
}

/// `doc` without the statements a failure names: the Body's solids ([`live_solids`]) once the held chain is dropped. A
/// carried failure on a statement no solid reads (an Op, an unnamed sketch's) changes no live solid, so the whole list
/// is used.
pub(crate) fn standing(doc: &Doc, faults: &[doc_core::Failure]) -> Doc {
    let named = |s: &Stmt| s.id().is_some_and(|id| faults.iter().any(|f| !f.id.is_empty() && f.id == id));
    Doc { tol: doc.tol, stmts: doc.stmts.iter().filter(|s| !named(s)).cloned().collect(), lines: Vec::new() }
}

impl Journal {
    /// THE fix reread: the writer's `text` with statement `i`'s line replaced by `new`, read back by `Doc::reread`;
    /// statement `i` of the result, None when it does not read or the statement count moved. SR590's `ref_fixes` and
    /// [`Journal::solid_fixes`] both enter here.
    fn retyped(&self, i: usize, text: &str, new: &str) -> Option<Stmt> {
        let mut all: Vec<&str> = text.lines().collect();
        *all.get_mut(i + 1)? = new;
        let d = self.doc.reread(&(all.join("\n") + "\n")).ok()?;
        d.stmts.get(i).filter(|_| d.stmts.len() == self.doc.stmts.len()).cloned()
    }

    /// The fixes for a held solid fault on statement `i` (document line `line`): NoProfile one per closed loop (its
    /// entity into `outer=`, photo.rs `renamed`), NoSuchEdge / AmbiguousEdge one per resolving edge name the statement
    /// does not already name (`[<words>]` into the refused name's place on the writer's line); each a Replace.
    fn solid_fixes(&self, i: usize, fault: &Fault, line: u32) -> Option<Vec<Fix>> {
        let text = doc_core::write(&self.doc);
        let own = text.lines().nth(i + 1)?.to_string();
        let news: Vec<String> = match fault {
            Fault::NoProfile { loops } => {
                let (Stmt::Extrude { outer, .. } | Stmt::Revolve { outer, .. }) = self.doc.stmts.get(i)? else { return None };
                loops.iter().filter(|l| *l != outer).map(|l| crate::photo::renamed(&own, &[(outer.clone(), l.clone())])).collect()
            }
            Fault::NoSuchEdge { name, edges } | Fault::AmbiguousEdge { name, edges } => {
                let bad = format!("[{name}]");
                if !own.contains(bad.as_str()) {
                    return None;
                }
                edges.iter().filter(|e| !own.contains(format!("[{e}]").as_str())).map(|e| own.replacen(bad.as_str(), &format!("[{e}]"), 1)).collect()
            }
            _ => return None,
        };
        let out: Vec<Fix> = news
            .iter()
            .filter(|n| **n != own)
            .filter_map(|n| self.retyped(i, &text, n))
            .map(|s| Fix { line, text: stmt_text(&s), road: FixRoad::Replace(i, s) })
            .collect();
        if out.is_empty() { None } else { Some(out) }
    }
}

// ---- VUGFACEJOURNALHOLDMANY (LEDGER SR609): every independent solid root is held, the card on the first ----
// SR598's [`hold`] took ONE root; a document with two or more independent roots refused, though `standing` already drops
// every named statement. Now every root (NoProfile / NoSuchEdge / AmbiguousEdge with an id) and its own `Upstream` chain
// is held. An `Upstream` joins the chain holding its source: doc_core names ONE source statement, so the chain is
// unique; were a source reachable from two roots, it follows the EARLIER root in line order. The card is offered for
// the FIRST held root in line order only ([`held_roots`]; a later root's row is marked by `faulted` and offers nothing),
// the cursor is put on it when a document opens held ([`Journal::load`]) and after a fix lands ([`Journal::accept_fix`]):
// each fix ONE Replace, ONE snapshot, ONE root restored, the next card following. deviation.rs `held_split` names the
// same list on the corner, `held=<a>,<b>`. VUGFACEJOURNALHOLDREST (SR611): a first root whose card offers nothing (no loop to
// offer, no resolving edge name) blocked every later card; now the card is offered for the first held root WITH a fix
// ([`Journal::fixable`]: [`Journal::solid_fixes`] non-empty, a parse-only retype, computed lazily in line order up to the
// first fixable root), the cursor put on it by `load` and after `accept_fix`; the roots before it stay held and marked
// and come first on the corner (`held=` is the same list, unchanged). No root with a fix: held, no card, the cursor on the
// first held root (SR609's rule).

/// The fault kinds a hold takes as a root: each carries the data its fix chooses from.
fn root_kind(f: &Fault) -> bool {
    matches!(f, Fault::NoProfile { .. } | Fault::NoSuchEdge { .. } | Fault::AmbiguousEdge { .. })
}

/// The held roots' ids in the failures' (line) order: the root-kind failures with an id. Only [`hold`] carries one
/// (an extrude / revolve / fillet / chamfer is always a solid's statement), so this is the held list; the first is the
/// root whose card is offered (VUGFACEJOURNALHOLDREST, SR611: the first that [`Journal::fixable`] holds).
pub(crate) fn held_roots(faults: &[doc_core::Failure]) -> Vec<String> {
    faults.iter().filter(|f| !f.id.is_empty() && root_kind(&f.fault)).map(|f| f.id.clone()).collect()
}

impl Journal {
    /// The cursor on the first held root with a fix (its card is the one offered; VUGFACEJOURNALHOLDREST, SR611), else on
    /// the first held root (no card); unchanged when nothing is held.
    fn to_held(&mut self) {
        let roots = held_roots(&self.faults);
        let Some(id) = roots.iter().find(|r| self.fixable(r)).or(roots.first()) else { return };
        if let Some(i) = self.doc.stmts.iter().position(|s| s.id() == Some(id.as_str())) {
            self.cursor = i;
        }
    }

    /// VUGFACEJOURNALHOLDREST (SR611): held root `id` has a fix: its row's carried failure gives [`Journal::solid_fixes`]
    /// at least one choice (NoProfile: a loop; NoSuchEdge / AmbiguousEdge: a resolving edge name; each rereads). A parse
    /// per candidate, no replay.
    fn fixable(&self, id: &str) -> bool {
        let Some(i) = self.doc.stmts.iter().position(|s| s.id() == Some(id)) else { return false };
        let Some(f) = self.faults.iter().find(|f| !f.id.is_empty() && f.id == id) else { return false };
        self.solid_fixes(i, &f.fault, self.doc.line(i)).is_some()
    }
}

// ---- VUGFACEJOURNALHOLDNOFIXWORD (LEDGER SR630): the note row says when no held root has a fix ----
// SR611 left a document whose held roots ALL offer nothing with marked rows, no card and no word why. The note row's
// ONE sayer is [`Journal::note_row`]: the note ([`Journal::note`]) unchanged while nothing is held or any held root has
// a fix ([`Journal::fixable`]), else the held list ([`held_roots`], line order, comma-joined as deviation.rs names it on
// the map's corner) and `no fix`, after the note with one space or alone: `fixed line 7: ... held=round no fix`,
// `held=round no fix`. `overlay` paints it in the note's style; `fix_overlay` puts a card one row above it. No field, no
// cache, no second row; deviation.rs `held_split` / `held_line` untouched.

impl Journal {
    /// The panel's note row: [`Journal::note`], plus `held=<a>,<b> no fix` when roots are held and none has a fix
    /// (VUGFACEJOURNALHOLDNOFIXWORD, SR630); None when there is neither.
    pub fn note_row(&self) -> Option<String> {
        let roots = held_roots(&self.faults);
        if roots.is_empty() || roots.iter().any(|r| self.fixable(r)) {
            return self.note.clone();
        }
        let word = format!("held={} no fix", roots.join(","));
        Some(match &self.note {
            Some(n) => format!("{n} {word}"),
            None => word,
        })
    }
}
